def prim_text(f_tex, x0_tex, y0_tex, dom=INF):
    return rf"Determinare la primitiva $F$ in ${dom}$ della funzione $f(x) = {f_tex}$ tale che $F({x0_tex}) = {y0_tex}$."


def pc_text(eq, conds):
    return r"Risolvere il problema di Cauchy $$\begin{cases} " + eq + r" \\ " + r" \\ ".join(conds) + r" \end{cases}$$"


def gen_text(eq):
    return rf"Determinare l'integrale generale dell'equazione differenziale $${eq}$$"


