FE = "Foglio di esercizi sulle equazioni differenziali, es. 1"


def ind(id_, f_tex, steps, prim, dom, topic, verif, nota=None, dv=False):
    d = dict(id=id_, tipo="manuale", cap=1, topic=topic, src=FI + ", integrali indefiniti",
             text=rf"Determinare $$\int {f_tex}\,dx.$$", steps=steps,
             fields=[{"label": "una primitiva", "kind": "prim", "expr": prim, "dom": dom}],
             verifica=[f"all(abs((diff({prim}, x) - ({verif})).subs(x, Rational(v)).evalf(30)) < 1e-12 for v in ['{dom[0] + 0.1:.2f}', '{(dom[0] + dom[1]) / 2 + 0.01:.2f}', '{dom[1] - 0.1:.2f}'])"],
             chk=[f"all(abs((diff(P('{prim}'), x) - (P('{verif}'))).subs(x, Rational(v)).evalf(30)) < 1e-12 for v in ['{dom[0] + 0.1:.2f}', '{(dom[0] + dom[1]) / 2 + 0.01:.2f}', '{dom[1] - 0.1:.2f}'])"])
    if nota:
        d["nota"] = nota
    if dv:
        d["daVerificare"] = True
    return d


